const UpdaterUI=(()=>{
 const state={status:'idle',version:'',packageSize:0,installerSize:0,progress:0,message:'',checking:false,checkedAt:0,prompted:new Set(),running:false,installing:false,promptTimer:null,sessionTimer:null};
 const bridge=()=>window.desktopUpdater;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const signedIn=()=>!!(window.cloudSession?.access_token&&window.cloudSession?.user);
 const bytes=value=>{const n=Math.max(0,Number(value)||0);if(n<1024)return Math.round(n)+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'};
 function transferText(event){const received=Math.max(0,Number(event.transferred)||0),total=Math.max(0,Number(event.total)||0),speed=Math.max(0,Number(event.bytesPerSecond)||0);if(!total&&!received)return 'Connecting to the update server…';const complete=total>0&&received>=total;const label=total&&total===state.installerSize?'Update launcher':total&&total===state.packageSize?'App package':'Update data';if(complete)return `${label}: ${bytes(received)} downloaded · Verifying and preparing remaining files…`;const remaining=speed>0&&total>received?Math.ceil((total-received)/speed):0;return `${label}: ${bytes(received)}${total?' / '+bytes(total):' downloaded'}${speed?' · '+bytes(speed)+'/s':''}${remaining?' · about '+remaining+'s left':''}`}
 function statusText(){if(!bridge())return 'Updates are available in the Windows desktop app.';if(state.running)return state.installing?'Applying update…':'Downloading update…';if(state.status==='available')return `Version ${state.version} is available.`;if(state.status==='downloaded')return `Version ${state.version} is ready.`;if(state.status==='current')return 'You’re up to date.';if(state.status==='error')return state.message;if(state.checking)return 'Checking for updates…';return 'Checks for the latest Sam’s Canvas release.'}
 function settingsRow(){return `<div class="settings-row updater-settings-row"><div><strong>Software updates</strong><p id="updaterSettingsStatus">${esc(statusText())}</p></div><div class="updater-settings-actions"><button class="secondary-btn" id="updaterNotesSettings">Release notes</button><button class="secondary-btn" id="updaterCheckSettings">Check for updates</button></div></div>`}
 function updateSettingsStatus(){const el=document.querySelector('#updaterSettingsStatus');if(el)el.textContent=statusText()}
 async function viewNotes(){if(!bridge())return toast('Release notes are available in the desktop app.');try{const notes=await bridge().releaseNotes();const body=String(notes.body||'').split(/\r?\n/).map(l=>`<p>${esc(l)}</p>`).join('');showModal(`<div class="modal-header"><div><div class="eyebrow">WHAT’S NEW</div><h2 id="modalTitle">${esc(notes.name)}</h2></div>${closeButton()}</div><div class="updater-release-notes">${body}</div><div class="modal-actions"><button class="primary-btn" data-close>Done</button></div>`)}catch(e){toast(e.message)}}
 function updateModal(mode){
  const views={available:{title:`Sam’s Canvas ${esc(state.version)}`,copy:'Update now to download, install, and reopen your workspace automatically.',action:'Update now'},progress:{title:`Updating to ${esc(state.version)}`,copy:state.message||'Connecting to GitHub…',action:''},installing:{title:'Applying your update',copy:'The download is verified. Sam’s Canvas will close briefly and reopen when installation finishes.',action:''},error:{title:'Update paused',copy:state.message||'Check your connection and try again.',action:'Try again'}};
  const v=views[mode];if(!v)return;const packageLabel=state.packageSize?'Full app package: '+bytes(state.packageSize):'';showModal(`<div class="update-dialog" data-update-mode="${mode}"><div class="update-orbit"><span>SC</span></div><div class="eyebrow">SOFTWARE UPDATE</div><h2 id="modalTitle">${v.title}</h2><p>${esc(v.copy)}</p>${mode==='progress'?`<small class="update-package-size" style="display:block;font-size:12px;color:var(--text-2);margin:8px 0">${packageLabel}</small><div class="update-progress"><span style="width:${Math.max(0,Math.min(100,state.progress))}%"></span></div>`:''}<div class="update-dialog-actions">${!state.running?'<button type="button" class="secondary-btn" id="updaterViewChanges">View release notes</button>':''}${v.action?`<button type="button" class="primary-btn" id="updaterMainAction">${v.action}</button>`:''}</div></div>`);
  document.querySelector('#updaterViewChanges')?.addEventListener('click',viewNotes);
  document.querySelector('#updaterMainAction')?.addEventListener('click',()=>{if(mode==='available'||state.status==='downloaded')download();else check(false)});
 }
 async function install(){if(state.installing)return;state.installing=true;updateModal('installing');try{if(typeof Collaboration!=='undefined')await Collaboration.flush();await bridge().install()}catch(e){state.installing=false;state.running=false;state.status='error';state.message=e.message;updateModal('error')}}
 async function download(){if(!bridge()||state.running||state.installing)return;clearTimeout(state.promptTimer);state.running=true;if(state.status==='downloaded'){await install();return}state.status='progress';state.progress=0;state.message='Connecting to GitHub…';updateModal('progress');try{await bridge().download()}catch(e){state.running=false;state.status='error';state.message=e.message||'The download could not finish.';updateModal('error')}updateSettingsStatus()}
 async function check(auto=false){if(!bridge()||state.checking||state.running||state.installing)return;clearTimeout(state.promptTimer);state.checking=true;state.status='checking';updateSettingsStatus();try{await bridge().check();state.checkedAt=Date.now();if(['available','downloaded'].includes(state.status)&&(!auto||!state.prompted.has(state.version))){state.prompted.add(state.version);state.promptTimer=setTimeout(()=>{if(!state.running&&!state.installing)updateModal('available')},100)}}catch(e){state.status='error';state.message=e.message;if(!auto)updateModal('error')}finally{state.checking=false;updateSettingsStatus()}}
 function onEvent(event){if(!event)return;switch(event.type){case'checking':if(!state.running)state.status='checking';break;case'available':state.version=event.version||'';state.packageSize=Math.max(0,Number(event.packageSize)||0);state.installerSize=Math.max(0,Number(event.installerSize)||0);if(!state.running)state.status='available';break;case'current':state.status='current';state.checkedAt=Date.now();break;case'progress':{
   state.status='progress';state.progress=Math.max(0,Math.min(100,Number(event.percent)||0));state.message=transferText(event);
   const bar=document.querySelector('.update-dialog[data-update-mode="progress"] .update-progress span'),copy=document.querySelector('.update-dialog[data-update-mode="progress"]>p');if(bar){bar.style.width=state.progress+'%';bar.style.visibility=Number(event.total)>0?'visible':'hidden'}if(copy)copy.textContent=state.message;break}
   case'downloaded':state.status='downloaded';state.version=event.version||state.version;if(state.running)install();break;
   case'error':state.status='error';state.message=event.message||'The update could not finish.';if(state.running){state.running=false;updateModal('error')}break;
  }updateSettingsStatus()}
 function sessionChanged(){if(!bridge()||!signedIn()||state.checkedAt||state.checking||state.sessionTimer)return;state.sessionTimer=setTimeout(()=>{state.sessionTimer=null;check(true)},1300)}
 function bindSettings(){document.querySelector('#updaterCheckSettings')?.addEventListener('click',()=>check(false));document.querySelector('#updaterNotesSettings')?.addEventListener('click',viewNotes);updateSettingsStatus()}
 if(bridge())bridge().onEvent(onEvent);window.addEventListener('online',()=>{if(state.status==='error'&&!state.running)check(true)});
 return{settingsRow,bindSettings,sessionChanged,check,viewNotes};
})();
